  "JSON to CSV": { es: "JSON a CSV", ar: "JSON إلى CSV", zh: "JSON 转 CSV", sw: "JSON kuwa CSV", sv: "JSON till CSV", de: "JSON zu CSV", pt: "JSON para CSV", fr: "JSON vers CSV" },
