  "Calculate a checksum first.": { es: "Primero calcula una suma de control.", ar: "احسب مجموعًا اختباريًا أولًا.", zh: "请先计算校验和。", sw: "Hesabu checksum kwanza.", sv: "Beräkna en kontrollsumma först.", de: "Berechne zuerst eine Prüfsumme.", pt: "Calcule um checksum primeiro.", fr: "Calculez d'abord une somme de contrôle." },
  "Checksum copied.": { es: "Suma de control copiada.", ar: "تم نسخ المجموع الاختباري.", zh: "校验和已复制。", sw: "Checksum imenakiliwa.", sv: "Kontrollsumman har kopierats.", de: "Prüfsumme kopiert.", pt: "Checksum copiado.", fr: "Somme de contrôle copiée." }
