  "File ↔ Base64": { es: "Archivo ↔ Base64", ar: "ملف ↔ Base64", zh: "文件 ↔ Base64", sw: "Faili ↔ Base64", sv: "Fil ↔ Base64", de: "Datei ↔ Base64", pt: "Arquivo ↔ Base64", fr: "Fichier ↔ Base64" },
  "Turn an image or any file into a Base64 data URL for CSS, HTML or JSON, or turn Base64 back into a file.": { es: "Convierte una imagen o cualquier archivo en una URL de datos Base64 para CSS, HTML o JSON, o vuelve a convertir Base64 en un archivo.", ar: "حوّل صورة أو أي ملف إلى رابط بيانات Base64 لاستخدامه في CSS أو HTML أو JSON، أو أعد Base64 إلى ملف.", zh: "把图片或任意文件转换为 Base64 数据 URL，用于 CSS、HTML 或 JSON；也可以把 Base64 还原为文件。", sw: "Geuza picha au faili lolote kuwa URL ya data ya Base64 kwa CSS, HTML au JSON, au rudisha Base64 kuwa faili.", sv: "Gör om en bild eller valfri fil till en Base64-data-URL för CSS, HTML eller JSON, eller gör om Base64 till en fil igen.", de: "Mach aus einem Bild oder einer beliebigen Datei eine Base64-Daten-URL für CSS, HTML oder JSON, oder mach aus Base64 wieder eine Datei.", pt: "Transforme uma imagem ou qualquer arquivo numa data URL Base64 para CSS, HTML ou JSON, ou transforme Base64 de volta em arquivo.", fr: "Transformez une image ou n'importe quel fichier en data URL Base64 pour CSS, HTML ou JSON, ou retransformez du Base64 en fichier." },
