  "Version 4 UUIDs from your browser's secure random numbers.": { es: "UUID versión 4 a partir de los números aleatorios seguros de tu navegador.", ar: "معرّفات UUID من الإصدار 4 من الأرقام العشوائية الآمنة في متصفحك.", zh: "使用浏览器的安全随机数生成第 4 版 UUID。", sw: "UUID za toleo la 4 kutoka namba nasibu salama za kivinjari chako.", sv: "Version 4-UUID:n från webbläsarens säkra slumptal.", de: "UUIDs der Version 4 aus den sicheren Zufallszahlen deines Browsers.", pt: "UUIDs versão 4 a partir dos números aleatórios seguros do seu navegador.", fr: "UUID version 4 issus des nombres aléatoires sécurisés de votre navigateur." },
  "Placeholder text copied.": { es: "Texto de relleno copiado.", ar: "تم نسخ النص المؤقت.", zh: "占位文字已复制。", sw: "Maandishi ya kujaza nafasi yamenakiliwa.", sv: "Platshållartexten kopierad.", de: "Platzhaltertext kopiert.", pt: "Texto de preenchimento copiado.", fr: "Texte de remplissage copié." },
